// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 dummy) internal {
        vm.assume(dummy == dummy);
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        assertTrue((reverted && address(c).balance == beforeBalance) || (!reverted && address(c).balance == 0));
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}

    fallback() external payable {}
}
